 package yomikai.domain.release.interactor

 import yomikai.core.common.preference.Preference
 import yomikai.core.common.preference.PreferenceStore
 import yomikai.domain.release.model.Release
 import yomikai.domain.release.service.ReleaseService
 import java.time.Instant
 import java.time.temporal.ChronoUnit

 class GetApplicationRelease(
     private val service: ReleaseService,
     private val preferenceStore: PreferenceStore,
 ) {

     private val lastChecked: Preference<Long> by lazy {
         preferenceStore.getLong(Preference.appStateKey("last_app_check"), 0)
     }

     suspend fun await(arguments: Arguments): Result {
         val now = Instant.now()

         // Limit checks to once every 3 days at most
         val nextCheckTime = Instant.ofEpochMilli(lastChecked.get()).plus(3, ChronoUnit.DAYS)
         if (!arguments.forceCheck && now.isBefore(nextCheckTime)) {
             return Result.NoNewUpdate
         }

         val release = service.latest(arguments) ?: return Result.NoNewUpdate

         lastChecked.set(now.toEpochMilli())

         // Check if latest version is different from current version
         val isNewVersion = isNewVersion(
             arguments.isPreview,
             arguments.commitCount,
             arguments.versionName,
             release.version,
         )
         return when {
             isNewVersion -> Result.NewUpdate(release)
             else -> Result.NoNewUpdate
         }
     }

     private fun isNewVersion(
         isPreview: Boolean,
         commitCount: Int,
         versionName: String,
         versionTag: String,
     ): Boolean {
         // Removes prefixes like "r" or "v"
         val newVersion = versionTag.replace("[^\\d.]".toRegex(), "")
         return if (isPreview) {
-            // Preview builds: based on releases in "mihonapp/mihon-preview" repo
+            // Preview builds: based on releases in the Yomikai preview repo
             // tagged as something like "r1234"
             newVersion.toInt() > commitCount
         } else {
-            // Release builds: based on releases in "mihonapp/mihon" repo
+            // Release builds: based on releases in the Yomikai repo
             // tagged as something like "v0.1.2"
             val oldVersion = versionName.replace("[^\\d.]".toRegex(), "")

             val newSemVer = newVersion.split(".").map { it.toInt() }
             val oldSemVer = oldVersion.split(".").map { it.toInt() }

             oldSemVer.mapIndexed { index, i ->
                 if (newSemVer[index] > i) {
                     return true
                 }
             }

             false
         }
     }

     data class Arguments(
         val isFoss: Boolean,
         val isPreview: Boolean,
         val commitCount: Int,
         val versionName: String,
         val repository: String,
         val forceCheck: Boolean = false,
     )

     sealed interface Result {
         data class NewUpdate(val release: Release) : Result
         data object NoNewUpdate : Result
         data object OsTooOld : Result
     }
 }

